  A(x, z, ry = 0, s = 1, dy = 0) {return this.at(x, this.gy(x, z) + dy, z, ry, s)},
  /* monta una pieza de esc-piezas.js */
  pon(L, x, z, ry = 0, s = 1, dy = 0) {const A = this.A(x, z, ry, s, dy); for (const [g, m] of L) A(g, m, 0, 0, 0)},
  /* grupo que se mueve, en el suelo */
  grupo(x, y, z, L) {const G = new THREE.Group(); G.position.set(x, y, z); fuse(L, G); this.g.add(G); return G},
  lago(m) {const [x, z, rx, rz] = this.m.pond, g = new THREE.CircleGeometry(1.12, 48).rotateX(-Math.PI / 2).scale(rx, 1, rz); const o = new THREE.Mesh(g, m); o.position.set(x, ICE_Y + .08, z); this.g.add(o)},
  farolas(l) {l.forEach(([x, z]) => {if (this.m.near(x, z, 10).d > 3.6) {this.farola(x, z); this.take(x, z, 1)}})},
  corro(cx, cz, r, n, w = 2) {const g = []; for (let k = 0; k < n; k++) {const a = k / n * 6.28 + this.r() * .3, d = r + this.r() * 2; g.push([cx + Math.cos(a) * d, cz + Math.sin(a) * d * .8, this.r() * 6, k % 2 ? w + this.r() * 1.6 : 0])} this.gente(g)},
  rotulo(txt, sub, x, z, w = 9) {const A = this.A(x, z); for (const q of [-1, 1]) A(CY(.18, .22, 5, 8), X.log, q * w * .42, 2.5, 0); A(PLN(w, w / 4), new THREE.MeshBasicMaterial({map: signTex(txt, sub), side: THREE.DoubleSide}), 0, 4.6, .24); this.take(x, z, w * .4)},

  /* ===== 2 · el país de los dulces ===== */
