    yield; for (const [r, y, n, m] of [[9.1, 6.7, 26, K.nata], [10, .6, 30, K.nata], [6.6, 12, 20, K.choco], [7.5, 6.8, 22, K.nata], [4.1, 16.4, 14, K.nata]]) for (let q = 0; q < n; q++) {const a = q / n * 6.2832; A(Z.remolino(.62, .85, 1.6, 5), m, Math.cos(a) * r, y, Math.sin(a) * r)} yield; for (let q = 0; q < 14; q++) {const a = q / 14 * 6.28; A(SPH(.8, 12, 9), K.fresa, Math.cos(a) * 8.4, 7.4, Math.sin(a) * 8.4); A(SPH(.6, 12, 9), q % 2 ? K.fresa : K.lila, Math.cos(a) * 5.8, 12.6, Math.sin(a) * 5.8)} for (let q = 0; q < 24; q++) {const a = q / 24 * 6.28; this.bulb(cx + Math.cos(a) * 9.7, this.gy(cx, cz) + 1.4, cz + Math.sin(a) * 9.7)}
    yield; for (let q = 0; q < 6; q++) {const a = q / 6 * 6.28; A(CY(.22, .22, 2.4, 8), [K.rosa, K.azul, K.menta][q % 3], Math.cos(a) * 3.2, 17.6, Math.sin(a) * 3.2); A(new THREE.ConeGeometry(.24, .9, 8), K.vela, Math.cos(a) * 3.2, 19.3, Math.sin(a) * 3.2)} this.glows.push([cx, this.gy(cx, cz) + .4, cz, 30]); this.take(cx, cz, 12);
